        .product-tabs { display:flex; gap:.75rem; padding:.5rem; background:rgba(255,255,255,.65); border:1px solid var(--line); border-radius:12px; box-shadow:0 10px 28px rgba(16,42,67,.06); }.product-tab { display:flex; align-items:center; gap:.75rem; flex:1; padding:.8rem 1rem; color:var(--muted); text-decoration:none; border-radius:8px; transition:background .2s ease, transform .2s ease; }.product-tab:hover { color:var(--ink); background:var(--mint); transform:translateY(-1px); }.product-tab.active { color:#fff; background:linear-gradient(110deg,var(--deep),#28666e); box-shadow:0 8px 18px rgba(11,31,51,.18); }.product-tab strong,.product-tab small { display:block; }.product-tab small { margin-top:.1rem; opacity:.72; font-size:.72rem; }.product-tab-icon { display:grid; place-items:center; width:2.25rem; height:2.25rem; border-radius:7px; background:var(--gold); color:var(--deep); font:700 .75rem Arial,sans-serif; }.message-panel,.payment-card { overflow:hidden; border-top:3px solid var(--aqua)!important; }.message-bubble { max-width:78%; box-shadow:0 6px 16px rgba(16,42,67,.06); }.message-out { color:#fff; background:linear-gradient(135deg,var(--deep),#28666e); }.message-in { background:var(--mint); }.composer { border-top:1px solid var(--line); padding-top:1rem; }.eyebrow { color:var(--coral); font:700 .68rem/1.2 Arial,sans-serif; letter-spacing:.12em; text-transform:uppercase; }.payment-callout { display:flex; align-items:center; justify-content:space-between; gap:1rem; padding:1.25rem 1.5rem; border:1px solid rgba(102,199,192,.55); border-radius:10px; background:linear-gradient(105deg,var(--mint),#fff); }.bank-summary { display:grid; gap:.2rem; padding:.85rem 1rem; border-left:3px solid var(--gold); background:var(--paper); }.status-pending { background:#fff0c7; color:#775600; }.status-funded { background:#dceeff; color:#124e78; }.status-released { background:#dff6ef; color:#146044; }.status-refunded { background:#fbe0e0; color:#8b2d2d; }.profile-section { padding:1.25rem; border:1px solid var(--line); border-radius:10px; background:linear-gradient(105deg,var(--paper),var(--surface)); }.profile-section-mark { padding:.4rem .6rem; border-radius:6px; background:var(--gold); color:var(--deep); font:700 .7rem Arial,sans-serif; }
        .dark-mode .product-tabs,.dark-mode .payment-callout,.dark-mode .profile-section { background:var(--surface); }.dark-mode .product-tab:hover { background:#1d4b5b; }.dark-mode .bank-summary { background:#102a39; }.dark-mode .message-in { background:#1b4a55; }.dark-mode .status-pending { background:#5a4d25; color:#ffe9a5; }.dark-mode .status-funded { background:#21496a; color:#c5e6ff; }.dark-mode .status-released { background:#1d513f; color:#c8ffea; }
