<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>(function(){const body=document.body,saved=localStorage.getItem('fpne-theme'),dark=saved?saved==='dark':window.matchMedia('(prefers-color-scheme: dark)').matches;if(dark)body.classList.add('dark-mode');const toggle=document.getElementById('themeToggle');if(toggle){const update=()=>{const isDark=body.classList.contains('dark-mode');toggle.textContent=isDark?'Light mode':'Dark mode';toggle.setAttribute('aria-pressed',String(isDark));};update();toggle.addEventListener('click',()=>{body.classList.toggle('dark-mode');localStorage.setItem('fpne-theme',body.classList.contains('dark-mode')?'dark':'light');update();});}document.querySelectorAll('input[type="password"]').forEach(input=>{const wrap=document.createElement('div');wrap.className='password-wrap';input.parentNode.insertBefore(wrap,input);wrap.appendChild(input);const button=document.createElement('button');button.type='button';button.className='password-toggle';button.textContent='Show';button.setAttribute('aria-label','Show password');button.addEventListener('click',()=>{const visible=input.type==='text';input.type=visible?'password':'text';button.textContent=visible?'Show':'Hide';button.setAttribute('aria-label',`${visible?'Show':'Hide'} password`);});wrap.appendChild(button);});})();</script>@stack('scripts')
